	'messages:userpage-userdoesnotexist-view' => 'vep:Kävutajan lehtpol’ "$1" ei ole registriruitud neciš wikiš.',
	'messages:blocked-notice-logextract' => 'vep:Nece {{GENDER:$1|kävutai}} om nügüd\' saubatud.
